// _unsigned_cloneMapUintString returns a copy of x, a map[uint]string, and nil
// for a nil x.
func _unsigned_cloneMapUintString(x map[uint]string) map[uint]string {
	if x == nil {
		return nil
	}
	c := make(map[uint]string, len(x))
	for mk, mv := range x {
		c[mk] = strings.Clone(mv)
	}
	return c
}

